var stdout = (msg.payload || '').trim();
if (stdout === '' || stdout === '[]') {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: You exited without leaving a review. You MUST use build review to leave your evaluation.';
    return msg;
}

try {
    var comments = JSON.parse(stdout);
    var bossComments = comments.filter(function(c) {
        return c.agent_id === 4 || c.role === 'boss';
    });
    if (bossComments.length === 0) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: No comments found. You MUST leave your evaluation.';
        return msg;
    }

    var lastComment = bossComments[bossComments.length - 1].content || '';
    var cleaned = lastComment.replace(/```json/g, '').replace(/```/g, '').trim();
    var payload = JSON.parse(cleaned);

    if (typeof payload.approval !== 'boolean' || !payload.reasoning) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: Missing approval (boolean) or reasoning (string) in your payload.';
        return msg;
    }

    msg.boss_approval = payload.approval;
    msg.boss_reasoning = payload.reasoning;
    msg.boss_eval_status = payload.approval ? 'approved' : 'rejected';
} catch (e) {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: Your review was not correctly formatted JSON. Please use build review.';
}
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var taskObj = Array.isArray(res) ? res[0] : res;
    var attempts = taskObj.approval_attempts;
    var lead_interventions = taskObj.lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "build task update --id " + msg.task.id + " --status stuck --agent-id 5 --reset-approval-attempts --inc-lead-interventions --audit-action escalate_to_lead";
        } else {
            msg.payload = "build task update --id " + msg.task.id + " --status failed --agent-id 1 --audit-action task_rejected";
        }
    } else {
        msg.payload = "build task update --id " + msg.task.id + " --agent-id 2 --audit-action assign_to_dev";
    }
} catch (e) {
    node.error('Error parsing boss attempts: ' + e.message);
    msg.payload = "build task update --id " + msg.task.id + " --agent-id 2";
}
return msg;

var formatErrMsg = msg.error_reason || 'System Error: Format validation failed.';
msg.payload = "build task update --id " + msg.task.id + " --inc-approval-attempts --comment-author-id 1 --comment \"" + formatErrMsg.replace(/"/g, "'") + "\"";
return msg;

